-- Dummy AgriPlot data for the SUSTAINIT database (sustainit_db) — NOT the averos DB.
-- AUTO-GENERATED by scripts/build-agriplot-seed.py from data/*.geojson — do not edit by hand.
-- Real plot geometries, one kabupaten per file. Idempotent.
-- All polygon-valid; all Outside Protected Area; a deterministic subset deforestation-detected.
--   sudo -u postgres psql -d sustainit_db -f /var/www/averos.land/scripts/agriplot-dummy-seed.sql

BEGIN;
-- owner name column may not exist in every deployment — ensure it before we fill it
ALTER TABLE sit_plots ADD COLUMN IF NOT EXISTS respondent_status text;

DELETE FROM sit_plots WHERE plot_id LIKE 'BDG-BARAT-%' OR plot_id LIKE 'BENER-MERIAH-%' OR plot_id LIKE 'BULELENG-%' OR plot_id LIKE 'ENDE-%' OR plot_id LIKE 'TABANAN-%' OR plot_id LIKE 'ACEH-DUMMY-%' OR plot_id LIKE 'KALBAR-DUMMY-%';
DELETE FROM sit_admin_boundary WHERE gid BETWEEN 90001 AND 90099;

VALUES ('a9100000-0000-4000-8000-000000000001',
        (SELECT id FROM sit_process ORDER BY id LIMIT 1),
        (SELECT id FROM sit_users ORDER BY created_at LIMIT 1),
        '127.0.0.1') ON CONFLICT (id) DO NOTHING;

-- bener_meriah_rev_1: 5 plots — Aceh / Bener Meriah

-- bandung_barat: 5 plots — Jawa Barat / Bandung Barat

-- buleleng: 5 plots — Bali / Buleleng

-- tabanan: 5 plots — Bali / Tabanan

-- ende: 5 plots — Nusa Tenggara Timur / Ende

COMMIT;
-- 25 plots, 5 deforestation-detected, all valid & outside protected.
